ALTER TABLE bulk_import_reference_rows ADD COLUMN IF NOT EXISTS organization_path JSONB NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE IF NOT EXISTS bulk_import_reference_entities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,business_id TEXT NOT NULL UNIQUE,entity_type TEXT NOT NULL,display_name TEXT NOT NULL,linked_business_id TEXT,organization_path JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,entity_type,display_name));
CREATE TABLE IF NOT EXISTS bulk_import_reference_links(reference_row_id UUID NOT NULL REFERENCES bulk_import_reference_rows(id) ON DELETE CASCADE,reference_entity_id UUID NOT NULL REFERENCES bulk_import_reference_entities(id) ON DELETE CASCADE,relationship TEXT NOT NULL DEFAULT 'mentioned',PRIMARY KEY(reference_row_id,reference_entity_id));
CREATE INDEX IF NOT EXISTS idx_reference_entity_linked ON bulk_import_reference_entities(company_id,linked_business_id);
